// Illustrative — enumerate paths, compare at the end, fresh visited per start.
public boolean exist(char[][] board, String word) {
    int m = board.length, n = board[0].length;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            boolean[][] visited = new boolean[m][n];   // re-allocated each start
            if (walk(board, word, r, c, new StringBuilder(), visited)) return true;
        }
    }
    return false;
}

private boolean walk(char[][] board, String word, int r, int c,
                     StringBuilder path, boolean[][] visited) {
    if (r < 0 || c < 0 || r >= board.length || c >= board[0].length || visited[r][c]) return false;
    path.append(board[r][c]);
    visited[r][c] = true;
    boolean done = false;
    if (path.length() == word.length()) {
        done = path.toString().equals(word);           // compare only at full length
    } else {
        done = walk(board, word, r + 1, c, path, visited)
            || walk(board, word, r - 1, c, path, visited)
            || walk(board, word, r, c + 1, path, visited)
            || walk(board, word, r, c - 1, path, visited);
    }
    visited[r][c] = false;
    path.deleteCharAt(path.length() - 1);
    return done;
}

