# Illustrative — enumerate paths, compare at the end, fresh visited per start.
def exist(self, board: list[list[str]], word: str) -> bool:
    m, n = len(board), len(board[0])

    def walk(r: int, c: int, path: str, visited: set) -> bool:
        if r < 0 or c < 0 or r >= m or c >= n or (r, c) in visited:
            return False
        path += board[r][c]
        visited.add((r, c))
        if len(path) == len(word):
            done = path == word                      # compare only at full length
        else:
            done = (walk(r + 1, c, path, visited) or walk(r - 1, c, path, visited)
                    or walk(r, c + 1, path, visited) or walk(r, c - 1, path, visited))
        visited.discard((r, c))
        return done

    for r in range(m):
        for c in range(n):
            if walk(r, c, "", set()):                 # fresh visited per start
                return True
    return False

