public boolean exist(char[][] board, String word) {
    int m = board.length, n = board[0].length;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            if (board[r][c] == word.charAt(0) && dfs(board, word, r, c, 0)) {
                return true;
            }
        }
    }
    return false;
}

private boolean dfs(char[][] board, String word, int r, int c, int k) {
    if (k == word.length()) return true;                 // matched every letter
    if (r < 0 || c < 0 || r >= board.length || c >= board[0].length
            || board[r][c] != word.charAt(k)) {
        return false;                                    // out of bounds, visited, or mismatch
    }
    char tmp = board[r][c];
    board[r][c] = '#';                                   // choose / mark visited
    boolean found = dfs(board, word, r + 1, c, k + 1)
                 || dfs(board, word, r - 1, c, k + 1)
                 || dfs(board, word, r, c + 1, k + 1)
                 || dfs(board, word, r, c - 1, k + 1);   // explore 4 neighbours
    board[r][c] = tmp;                                   // un-choose / restore
    return found;
}

